# Define the graph
edges = [
    (0,5), (0,7), (0,9), (0,13), (0,14), (1,2), (2,9), (2,20), (2,23), (3,6),
    (3,11), (4,8), (4,12), (4,17), (4,18), (4,19), (4,23), (5,6), (5,9), (5,10),
    (5,14), (5,17), (5,18), (5,21), (6,10), (6,17), (7,22), (8,17), (8,22), (8,24),
    (9,13), (9,21), (10,12), (10,14), (11,16), (13,20), (13,23), (14,16), (14,23),
    (14,24), (15,23), (16,19), (16,21), (16,22), (16,23), (17,18), (19,20), (19,23),
    (19,24), (20,22)
]

# Build adjacency list
adj = {i: [] for i in range(25)}
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

# Backtracking coloring algorithm
coloring = {}

def is_safe(node, color):
    for neighbor in adj[node]:
        if neighbor in coloring and coloring[neighbor] == color:
            return False
    return True

def backtrack(node):
    if node == 25:
        return True
    for color in range(3):
        if is_safe(node, color):
            coloring[node] = color
            if backtrack(node + 1):
                return True
            del coloring[node]
    return False

if backtrack(0):
    print("SATISFIABLE")
    result = [coloring[i] for i in range(25)]
    print(result)
else:
    print("UNSATISFIABLE")
